Rules.InvariantScript:
Set(
    varUtenteCorrente,
    LookUp(UserRoles, Email = txtEmail.Text)
);
If(
    IsBlank(varUtenteCorrente),
    Notify("Email non trovata. Verifica e riprova.", NotificationType.Error),
    Set(
        varRuoloUtente,
        Switch(
            Lower(Trim(varUtenteCorrente.Role)),
            "agent", "Agent",
            "agente", "Agent",
            "manager", "Manager",
            "office", "Office",
            varUtenteCorrente.Role
        )
    );
    Set(varAccessoEffettuato, true);
    Navigate(scrLoading)
)
